    // this type used to indicate the monitor state
    typedef enum {
        NOT_MON      = 0,    // no do monitor
        WAIT_FOR_GEN = 1,    // wait for a specific state gen
        LASTING      = 2,    // monitor whether a specific state lasting
        WAIT_FOR_CLR = 3     // wait for a specific state clear
    } oh_mon_state_e;

    // this type used to indicate the sm, tcmi, pm of otn
    typedef enum {
        SM    = 0,  
        TCM1  = 1,
        TCM2  = 2,
        TCM3  = 3,
        TCM4  = 4,
        TCM5  = 5,
        TCM6  = 6,
        PM    = 7
    } otn_xm_e;

    // this type used to indicate the alarm state in dut
    typedef enum {
        NOTHING = 'b000,  // there is not any alarm
        GEN     = 'b111,  // alarm has been generated
        CLR     = 'b010,  // alarm has been cleared
        NOCHK   = 'b110,
        INIT    = 'b100
    } oh_alarm_state_e;

    typedef enum {
        JC    = 0,        // ABMP
        GMP   = 1,        // GMP
        CBYTE = 2         // OTU3V
